def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    inc = [0] * n
    dec = [0] * n

    inc[0] = arr[0]
    for i in range(1, n):
        inc[i] = max(arr[i], inc[i-1] + arr[i])

    dec[n-1] = arr[n-1]
    for i in range(n-2, -1, -1):
        dec[i] = max(arr[i], dec[i+1] + arr[i])

    max_sum = float("-inf")
    for i in range(n):
        if i == 0 or i == n-1:
            current = max(inc[i], dec[i])
        else:
            current = inc[i-1] + dec[i]
        if current > max_sum:
            max_sum = current

    return max_sum if max_sum != float("-inf") else max(inc)

